//! Loopback-only integration peer. Uses ephemeral certificates generated by the
//! Python test fixture, never a browser or a substitute for the product client.
use neqo_common::{Datagram, Header};
use neqo_http3::{
    Http3OrWebTransportStream, Http3Parameters, Http3Server, Http3ServerEvent as Event,
    SessionAcceptAction,
    webtransport::{ServerEvent as Wt, ServerSession},
};
use neqo_transport::{Output, RandomConnectionIdGenerator, StreamType};
use std::{
    cell::RefCell,
    io::{self, Write},
    net::UdpSocket,
    rc::Rc,
    time::{Duration, Instant},
};

struct Pending {
    stream: Http3OrWebTransportStream,
    data: Vec<u8>,
    fin: bool,
}
fn main() {
    let args: Vec<_> = std::env::args().collect();
    nss::init_db(&args[1]).unwrap();
    let now = Instant::now();
    let mut server = Http3Server::new(
        now,
        &["peer"],
        &["h3"],
        nss::AntiReplay::new(now, Duration::from_secs(10), 7, 14).unwrap(),
        Rc::new(RefCell::new(RandomConnectionIdGenerator::new(10))),
        Http3Parameters::default().webtransport(true),
        None,
    )
    .unwrap();
    let socket = UdpSocket::bind("127.0.0.1:0").unwrap();
    socket
        .set_read_timeout(Some(Duration::from_millis(2)))
        .unwrap();
    println!("{}", socket.local_addr().unwrap().port());
    io::stdout().flush().unwrap();
    let mut sessions: Vec<ServerSession> = Vec::new();
    let mut pending: Vec<Pending> = Vec::new();
    let mut buffer = [0; 65536];
    loop {
        let input = match socket.recv_from(&mut buffer) {
            Ok((size, remote)) if size > 0 => Some(Datagram::new(
                remote,
                socket.local_addr().unwrap(),
                Default::default(),
                buffer[..size].to_vec(),
            )),
            Ok(_) => None,
            Err(e)
                if matches!(
                    e.kind(),
                    io::ErrorKind::WouldBlock | io::ErrorKind::TimedOut
                ) =>
            {
                None
            }
            Err(e) => panic!("{e}"),
        };
        let mut output = server.process(input, Instant::now());
        for _ in 0..256 {
            if let Output::Datagram(packet) = output {
                socket.send_to(&packet, packet.destination()).unwrap();
                output = server.process_output(Instant::now());
            } else {
                break;
            }
        }
        while let Some(event) = server.next_event() {
            match event {
                Event::Headers {
                    stream,
                    headers,
                    fin,
                } => {
                    let method = headers
                        .iter()
                        .find(|h| h.name() == ":method")
                        .unwrap()
                        .value();
                    if method == b"GET" {
                        let body = b"<!doctype html><title>Native HTTP3</title><script>globalThis.h3Value=42</script>".to_vec();
                        stream
                            .send_headers(&[
                                Header::new(":status", "200"),
                                Header::new("content-type", "text/html"),
                                Header::new("content-length", body.len().to_string()),
                            ])
                            .unwrap();
                        pending.push(Pending {
                            stream,
                            data: body,
                            fin: true,
                        });
                    } else {
                        stream
                            .send_headers(&[Header::new(":status", "200")])
                            .unwrap();
                        if fin {
                            let _ = stream.stream_close_send(Instant::now());
                        }
                    }
                }
                Event::Data { stream, data, fin } => {
                    if stream.stream_id().is_uni() {
                        if let Some(session) = sessions.iter().find(|s| s.conn == stream.conn) {
                            let mut echo = b"uni:".to_vec();
                            echo.extend(&data);
                            let _ = session.send_datagram(&echo, None, Instant::now());
                        }
                    } else if data == b"reset" {
                        let _ = stream.stream_stop_sending(0x52e4a40fa8db + 7);
                        let _ = stream.stream_reset_send(0x52e4a40fa8db + 7);
                    } else {
                        if let Some(item) = pending.iter_mut().find(|p| {
                            p.stream.conn == stream.conn
                                && p.stream.stream_id() == stream.stream_id()
                        }) {
                            item.data.extend(data);
                            item.fin |= fin;
                        } else {
                            pending.push(Pending { stream, data, fin });
                        }
                    }
                }
                Event::WebTransport(Wt::NewSession { session, headers }) => {
                    let path = headers
                        .iter()
                        .find(|h| h.name() == ":path")
                        .unwrap()
                        .value();
                    if path == b"/reject" {
                        session
                            .response(
                                &SessionAcceptAction::Reject(vec![Header::new(":status", "403")]),
                                Instant::now(),
                            )
                            .unwrap();
                        continue;
                    }
                    let protocol = headers.iter().any(|h| h.name() == "wt-available-protocols");
                    let accept = if protocol {
                        SessionAcceptAction::AcceptWith(vec![Header::new(
                            "wt-protocol",
                            "\"echo\"",
                        )])
                    } else {
                        SessionAcceptAction::Accept
                    };
                    session.response(&accept, Instant::now()).unwrap();
                    for (kind, data) in [
                        (StreamType::UniDi, b"server uni".as_slice()),
                        (StreamType::BiDi, b"server bidi".as_slice()),
                    ] {
                        let stream = session.create_stream(kind).unwrap();
                        pending.push(Pending {
                            stream,
                            data: data.to_vec(),
                            fin: true,
                        });
                    }
                    sessions.push(session);
                }
                Event::WebTransport(Wt::Datagram { session, datagram }) => {
                    if datagram.as_ref() == b"export" {
                        let mut data = [0; 32];
                        session
                            .export_keying_material(b"test", b"context", &mut data)
                            .unwrap();
                        session.send_datagram(&data, None, Instant::now()).unwrap();
                    } else if datagram.as_ref() == b"close" {
                        session
                            .close_session(42, "peer closed", Instant::now())
                            .unwrap();
                    } else {
                        session
                            .send_datagram(datagram.as_ref(), None, Instant::now())
                            .unwrap();
                    }
                }
                _ => {}
            }
        }
        pending.retain_mut(|item| {
            if !item.data.is_empty() {
                match item.stream.send_data(&item.data, Instant::now()) {
                    Ok(count) => {
                        item.data.drain(..count);
                    }
                    Err(_) => return false,
                }
            }
            if item.data.is_empty() {
                if item.fin {
                    let _ = item.stream.stream_close_send(Instant::now());
                }
                false
            } else {
                true
            }
        });
    }
}
